/**
 * @name pip: untrusted input to subprocess and shell commands
 * @description Find flows from remote/user-controlled input into subprocess and shell execution APIs within pip internals.
 * @kind path-problem
 * @problem.severity error
 * @id pip/subprocess-user-input
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PipSubprocessConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      sink = call.getArg(0) and
      (
        call = API::moduleImport("subprocess").getMember(["Popen", "call", "check_call", "check_output", "run"]).getACall() or
        call = API::moduleImport("os").getMember(["system", "popen"]).getACall()
      )
    )
  }
}

module PipSubprocessFlow = TaintTracking::Global<PipSubprocessConfig>;
import PipSubprocessFlow::PathGraph

from PipSubprocessFlow::PathNode source, PipSubprocessFlow::PathNode sink
where PipSubprocessFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches subprocess or shell command $@.", source.getNode(), "user input"

