/**
 * @name Insecure file write with user-controlled path in pip
 * @description Detects flows from remote/user input into file system write operations in pip
 * @kind path-problem
 * @problem.severity error
 * @id pip/path-traversal-file-write
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PipFileWriteConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      (
        // open(..., 'w'/'a'/etc)
        call = API::builtin("open").getACall() and
        sink = call.getArg(0)
      ) or (
        // os.remove, os.unlink, os.rmdir, os.makedirs, os.mkdir
        call = API::moduleImport("os").getMember(["remove", "unlink", "rmdir", "makedirs", "mkdir"]).getACall() and
        sink = call.getArg(0)
      ) or (
        // shutil.rmtree, shutil.copy, shutil.move
        call = API::moduleImport("shutil").getMember(["rmtree", "copy", "move", "copytree"]).getACall() and
        sink = call.getArg(0)
      )
    )
  }
}

module PipFileWriteFlow = TaintTracking::Global<PipFileWriteConfig>;
import PipFileWriteFlow::PathGraph

from PipFileWriteFlow::PathNode source, PipFileWriteFlow::PathNode sink
where PipFileWriteFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into file-system operation $@, potential path traversal or arbitrary file access.", sink.getNode(), "file path"

/**
 * @name Insecure command execution via os.system/popen in pip
 * @description Detects flows from remote/user input into command execution helpers using os.system/popen or subprocess.* with shell=True
 * @kind path-problem
 * @problem.severity error
 * @id pip/command-injection-shell
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PipShellExecConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      (
        // os.system, os.popen
        call = API::moduleImport("os").getMember(["system", "popen"]).getACall() and
        sink = call.getArg(0)
      ) or (
        // subprocess.* with shell=True, first argument is command string/list
        call = API::moduleImport("subprocess").getMember(["call", "run", "Popen", "check_call", "check_output"]).getACall() and
        exists(int i |
          i = 0 and sink = call.getArg(i)
        )
      )
    )
  }
}

module PipShellExecFlow = TaintTracking::Global<PipShellExecConfig>;
import PipShellExecFlow::PathGraph

from PipShellExecFlow::PathNode source, PipShellExecFlow::PathNode sink
where PipShellExecFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into shell command execution $@, potential command injection.", sink.getNode(), "command"
